function ownCertificate(stored:typeof TARGETS[number]['certificate']):ReviewedU7050GrowingCertificate{ensure(stored.syntax==='MQ'&&stored.initialKind==='single-quadratic','灐 own MQ certificate kind');return deepFreeze({syntax:'MQ' as const,initialKind:'single-quadratic' as const,T:stored.T,K:stored.K,initialArcMax:7 as const,storedBounds:stored,notRasterProof:true as const,notPreviousMaskConnectivityProof:true as const,notFullSweepProof:true as const})}
